#!/usr/bin/env node
/**
 * Self-check for `perf/lib/attendance-protocol.js`, the protocol code the k6 script signs with.
 * Runs on plain Node 20, no k6 and no backend needed:
 *
 *   node perf/check-protocol.mjs
 *
 * 1. Canonical builders: every punch and envelope case in the shared fixture
 *    `core/hr/src/test/resources/attendance-protocol/fixtures/canonical.json` (generated by the Java
 *    `CanonicalFixtureGeneratorTest` from `AppSignatures`) must reproduce `canonicalHex` and
 *    `canonicalSha256` byte for byte. This is the same assertion the TypeScript package makes.
 * 2. DER encoder: fixed r/s vectors with a leading 0x00 to strip and a high bit to pad; then
 *    real P-256 signatures from WebCrypto, DER-encoded here and verified by Node's OpenSSL-backed
 *    `crypto.verify(..., { dsaEncoding: 'der' })`, which is as strict about minimal DER as Java's
 *    `SHA256withECDSA`. `derToRawEcdsa` must give the raw bytes back.
 * 3. Byte helpers (`utf8Bytes`, Base64) against Node's `Buffer`.
 *
 * Exit code 0 means every check passed; the first failure prints and exits 1.
 */
import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import nodeCrypto from 'node:crypto';

import {
  base64Decode,
  base64Encode,
  bytesToHex,
  canonicalPunchPayload,
  canonicalRequestEnvelope,
  derToRawEcdsa,
  formatPhoneTime,
  hexToBytes,
  parsePhoneTime,
  rawToDerEcdsa,
  sha256Hex,
  utf8Bytes,
  ECDSA_P256,
  ECDSA_SHA256,
} from './lib/attendance-protocol.js';

const here = dirname(fileURLToPath(import.meta.url));
const FIXTURE =
  process.env.CANONICAL_FIXTURE ||
  resolve(here, '../core/hr/src/test/resources/attendance-protocol/fixtures/canonical.json');

let checks = 0;
function ok(condition, message) {
  checks++;
  if (!condition) {
    console.error(`FAIL: ${message}`);
    process.exit(1);
  }
}
function same(actual, expected, message) {
  ok(actual === expected, `${message}\n  expected ${expected}\n  actual   ${actual}`);
}

// ---- 1. canonical builders vs the Java-generated fixture --------------------------------------

const fixture = JSON.parse(readFileSync(FIXTURE, 'utf8'));
same(fixture.punchVersion, 'SKAT-PUNCH-1', 'fixture punch version');
same(fixture.envelopeVersion, 'SKAT-REQ-1', 'fixture envelope version');

for (const c of fixture.punches) {
  const bytes = canonicalPunchPayload({
    ...c.input,
    phoneTime: parsePhoneTime(c.input.phoneTime),
  });
  same(bytesToHex(bytes), c.canonicalHex, `punch "${c.name}": canonical bytes`);
  same(await sha256Hex(bytes), c.canonicalSha256, `punch "${c.name}": sha256`);
  same(formatPhoneTime(parsePhoneTime(c.input.phoneTime)), c.input.phoneTime, `punch "${c.name}": phoneTime`);
}

for (const c of fixture.envelopes) {
  const body = hexToBytes(c.input.bodyHex);
  same(bytesToHex(utf8Bytes(c.input.bodyUtf8)), c.input.bodyHex, `envelope "${c.name}": utf8Bytes(body)`);
  same(await sha256Hex(body), c.bodySha256, `envelope "${c.name}": bodySha256`);
  const bytes = await canonicalRequestEnvelope({ ...c.input, body });
  same(bytesToHex(bytes), c.canonicalHex, `envelope "${c.name}": canonical bytes`);
  same(await sha256Hex(bytes), c.canonicalSha256, `envelope "${c.name}": sha256`);
}
console.log(`canonical fixture: ${fixture.punches.length} punches, ${fixture.envelopes.length} envelopes match`);

// ---- 2. DER encoder -----------------------------------------------------------------------------

function vector(rHex, sHex) {
  return new Uint8Array([...hexToBytes(rHex.padStart(64, '0')), ...hexToBytes(sHex.padStart(64, '0'))]);
}
// r has the high bit set → 0x00 pad, 33 bytes; s has leading zero bytes → stripped to 31 bytes.
{
  const r = 'ff'.repeat(32);
  const s = '00' + '7f' + 'ab'.repeat(30);
  const der = rawToDerEcdsa(vector(r, s));
  same(
    bytesToHex(der),
    '30' + '44' + '02' + '21' + '00' + r + '02' + '1f' + '7f' + 'ab'.repeat(30),
    'DER: pad a high-bit r, strip a leading-zero s',
  );
  same(bytesToHex(derToRawEcdsa(der)), bytesToHex(vector(r, s)), 'DER → raw round trip (padded/stripped)');
}
// Both components small: 1 byte each.
{
  const der = rawToDerEcdsa(vector('01', '7f'));
  same(bytesToHex(der), '3006' + '020101' + '02017f', 'DER: one-byte integers');
}
// r = 0x80 exactly needs a pad; s = 0x00 stays one zero byte (never empty).
{
  const der = rawToDerEcdsa(vector('80', '00'));
  same(bytesToHex(der), '3007' + '02020080' + '020100', 'DER: 0x80 padded, zero kept as 02 01 00');
}

// Real signatures: WebCrypto raw r||s → our DER → OpenSSL verify (strict DER) and raw round trip.
const ROUNDS = Number(process.env.DER_ROUNDS || 500);
const keyPair = await crypto.subtle.generateKey(ECDSA_P256, true, ['sign', 'verify']);
const spki = Buffer.from(await crypto.subtle.exportKey('spki', keyPair.publicKey));
const publicKey = nodeCrypto.createPublicKey({ key: spki, format: 'der', type: 'spki' });
let padded = 0;
let stripped = 0;
for (let i = 0; i < ROUNDS; i++) {
  const message = nodeCrypto.randomBytes(1 + (i % 200));
  const raw = new Uint8Array(await crypto.subtle.sign(ECDSA_SHA256, keyPair.privateKey, message));
  same(raw.length, 64, 'WebCrypto returns raw r||s for P-256');
  const der = rawToDerEcdsa(raw);
  if (raw[0] & 0x80 || raw[32] & 0x80) padded++;
  if (raw[0] === 0 || raw[32] === 0) stripped++;
  ok(
    nodeCrypto.verify('sha256', message, { key: publicKey, dsaEncoding: 'der' }, der),
    `round ${i}: OpenSSL rejects our DER signature ${bytesToHex(der)}`,
  );
  ok(
    nodeCrypto.verify('sha256', message, { key: publicKey, dsaEncoding: 'ieee-p1363' }, raw),
    `round ${i}: sanity, raw signature verifies as P1363`,
  );
  same(bytesToHex(derToRawEcdsa(der)), bytesToHex(raw), `round ${i}: DER → raw round trip`);
  // A flipped bit must not verify (the encoder is not padding the check away).
  const tampered = Uint8Array.from(der);
  tampered[tampered.length - 1] ^= 0x01;
  ok(
    !nodeCrypto.verify('sha256', message, { key: publicKey, dsaEncoding: 'der' }, tampered),
    `round ${i}: tampered DER signature must not verify`,
  );
}
ok(padded > 0, `expected at least one high-bit component in ${ROUNDS} signatures (got ${padded})`);
console.log(`DER: ${ROUNDS} WebCrypto signatures verified by OpenSSL (${padded} padded, ${stripped} stripped)`);

// ---- 3. byte helpers ----------------------------------------------------------------------------

for (const text of ['', 'a', 'ab', 'abc', 'हाँ — I agree', '😀 emoji', '{"version":2}']) {
  const expected = Buffer.from(text, 'utf8');
  same(bytesToHex(utf8Bytes(text)), expected.toString('hex'), `utf8Bytes(${JSON.stringify(text)})`);
  same(base64Encode(utf8Bytes(text)), expected.toString('base64'), `base64Encode(${JSON.stringify(text)})`);
  same(
    bytesToHex(base64Decode(expected.toString('base64'))),
    expected.toString('hex'),
    `base64Decode(${JSON.stringify(text)})`,
  );
}
for (let n = 0; n < 70; n++) {
  const bytes = nodeCrypto.randomBytes(n);
  same(base64Encode(new Uint8Array(bytes)), bytes.toString('base64'), `base64Encode random ${n} bytes`);
}

console.log(`OK: ${checks} checks passed`);
